#include <iostream>
#include <vector>
using namespace std;

int main() {   //@ @layout open:container
    vector<int> arr = {3, 1, 4};   //@ @tts [next] 準備一個有三個數字的陣列
    for (int i = 0; i < 3; i++) {   //@ @tts [next] 一格一格處理 | @2 [next] 看看還有沒有下一格
        arr[i] = arr[i] * 2;   //@ @guide {arr[i]:orange} @tts [next] 現在輪到第 {i} 格，先講一句話，[anim]看這一格 @layout pop:arr
    }
    cout << arr[0] << endl;   //@ @guide {arr} @tts [next] 全部乘完了
    return 0;   //@ @tts [continue] 程式結束
}
